// The Worker's entry point (wrangler.jsonc "main"): the OpenNext build of the
// app (.open-next/worker.js, written by `opennextjs-cloudflare build`), wrapped
// by Sentry (./sentry.ts).
import * as Sentry from "@sentry/cloudflare";
// Generated by the build, so missing before one (ts-expect-error would then
// fail after one).
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import openNext from "../.open-next/worker.js";
import { sentryOptions } from "./sentry";

// The ISR revalidation queue's Durable Object (wrangler.jsonc durable_objects).
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
export { DOQueueHandler } from "../.open-next/worker.js";

export default Sentry.withSentry((env: CloudflareEnv) => sentryOptions(env), openNext as Parameters<typeof Sentry.withSentry>[1]);
